#include <iostream>
#include <string>
#include <vector>

using namespace std;

char letterToDigit(char c) {
    if (c >= 'a' && c <= 'c') return '2';
    if (c >= 'd' && c <= 'f') return '3';
    if (c >= 'g' && c <= 'i') return '4';
    if (c >= 'j' && c <= 'l') return '5';
    if (c >= 'm' && c <= 'o') return '6';
    if (c >= 'p' && c <= 's') return '7';
    if (c >= 't' && c <= 'v') return '8';
    if (c >= 'w' && c <= 'z') return '9';
    return '0';
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string n;
    if (!(cin >> n)) return 0;

    int m;
    if (!(cin >> m)) return 0;

    int count = 0;
    for (int i = 0; i < m; ++i) {
        string s;
        cin >> s;

        if (s.length() != n.length()) {
            continue;
        }

        bool match = true;
        for (size_t j = 0; j < s.length(); ++j) {
            if (letterToDigit(s[j]) != n[j]) {
                match = false;
                break;
            }
        }

        if (match) {
            count++;
        }
    }

    cout << count << "\n";

    return 0;
}
